  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  // Try to resume if suspended (iOS requirement). 
  // If we are in a timeout (lost gesture), this might fail or hang, so we timeout the resume attempt.
  if (audioCtx.state === 'suspended') {
      try {
        await Promise.race([
            audioCtx.resume(),
            new Promise((_, reject) => setTimeout(() => reject('timeout'), 200))
        ]);
      } catch (e) {
        // Expected on iOS if no user gesture. We will proceed without audio.
      }
  }

  // Only add audio track if context is actually running.
  // On iOS Safari, adding a track from a suspended context can freeze MediaRecorder.
  const useAudio = audioCtx.state === 'running';

  const dest = audioCtx.createMediaStreamDestination();
  // We still create oscillators so logic remains same, but they won't be recorded if !useAudio
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const MIN_FILL_MS = 2000;
  const FILL_MS = Math.max(MIN_FILL_MS, Math.min(8000, moves.length * 100)); 
  const INTRO_MS = 500; 
  const OUTRO_MS = 2000; 

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 5; 
  const availableFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);

  for (let i = 0; i < moveCount; i++) {
      const progress = i / Math.max(1, moveCount - 1);
      moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableFrames);
  }

  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t);
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // Header
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // Timer
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // Board Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Grid
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];
              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 5) numScale = 1.0 + (0.5 * (1 - (age / 5)));

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const alpha = Math.min(1, outroAge / 10);
          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;
          ctx.beginPath();
          ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  if (useAudio) {
      const audioTrack = dest.stream.getAudioTracks()[0];
      if (audioTrack) {
          stream.addTrack(audioTrack);
      }
  }

  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', 
    'video/mp4',
    'video/webm; codecs=vp9', 
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 3000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timer
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') mediaRecorder.stop();
  }, TOTAL_DURATION_MS + 3000);

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // Start Recording
  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  // Schedule Audio (only if enabled)
  const startTime = audioCtx.currentTime;
  if (useAudio) {
      for (let i = 0; i < moveCount; i++) {
          const timeOffset = moveFrames[i] / FPS; 
          playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
      }
      const victoryTime = (INTRO_FRAMES + FILL_FRAMES) / FPS;
      playVictory(startTime + victoryTime + 0.05);
  }

  // Visual Loop (Decoupled)
  const startWallTime = performance.now();
  const render = () => {
      try {
          const now = performance.now();
          const elapsed = (now - startWallTime) / 1000;
          const currentFrame = Math.floor(elapsed * FPS);

          if (currentFrame > TOTAL_FRAMES + 2) { 
              if (mediaRecorder.state === 'recording') mediaRecorder.stop();
              return;
          }

          drawBoard(currentFrame);
          requestAnimationFrame(render);
      } catch (e) {
          console.error("Render loop error", e);
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
      }
  };
  requestAnimationFrame(render);

  return recordingPromise;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r) => saveProgress(b, s, r),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        // IMPORTANT: No setTimeout here. 
        // We must start the audio context handling synchronously with the user gesture (if triggered by button).

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // 2. Smart Fallback: If no moves found (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length === 0) {
                    for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                    }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `sudoku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  return (
    <>
      <div className="w-full flex flex-col items-center relative z-40 pt-[20px] pb-4">
          <div className="w-full max-w-md px-6 flex items-start justify-between">
              {/* Left Column: Back Button */}
              <div className="w-12">
                  <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon">
                      <Icons.Back className="w-6 h-6" />
                  </button>
              </div>

              {/* Center Column: Title & Timer */}
              <div className="flex-1 flex flex-col items-center animate-fade-in mt-2">
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest leading-none mb-1.5">{difficulty} &bull; LEVEL {levelId}</span>
                  {settings.showTimer && (
                      <span className="text-2xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  )}
              </div>

              {/* Right Column: Actions */}
              <div className="w-12 flex justify-end gap-1">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
