                    </div>
                </div>
            </div>
        </div>
    );
};

export enum Difficulty {
  SuperEasy = 'Super Easy',
  Easy = 'Easy',
  Normal = 'Normal',
  Hard = 'Hard',
  Intense = 'Intense',
  Impossible = 'Impossible',
}

export type CellValue = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 | null;

export interface Cell {
  row: number;
  col: number;
  value: CellValue;
  isFixed: boolean;
  notes: number[];
  isError?: boolean;
  isMarkedWrong?: boolean; // For Scan skill
  isRevealed?: boolean; // For Reveal skill
}

export type Board = Cell[][];

export interface LevelProgress {
  levelId: number; // 1 to 30
  difficulty: Difficulty;
  status: 'locked' | 'not-started' | 'in-progress' | 'completed';
  timeElapsed: number;
  lastPlayed?: number; // timestamp
  boardState?: Cell[][]; // simplified for storage
  bestTime?: number; // Personal best time in seconds
  scanUses?: number; // Remaining scan uses
  revealUses?: number; // Remaining reveal uses
}

export interface AppSettings {
  sound: boolean;
  highlight: boolean;
  autoEraseNotes: boolean; // NEW: Remove notes when number is placed
  vibration: boolean;
  showTimer: boolean;
  appearance: 'system' | 'light' | 'dark';
  digitFirst: boolean; // NEW: Input mode
  screenWakeLock: boolean; // NEW: Keep screen on
  generateReplay: boolean; // NEW: Generate video replay on completion
}

export interface StoredData {
  settings: AppSettings;
  points: number;
  progress: Record<string, LevelProgress>; // key: "Difficulty-LevelID"
  purchasedBackgrounds: string[];
  selectedBackground: string | null;
  purchasedNumberColors: string[];
  selectedNumberColor: string;
  purchasedSkills: string[];
  enabledSkills: string[]; // NEW: Tracks which skills are toggled ON for the game
  purchasedSoundPacks: string[]; // NEW
  selectedSoundPack: string; // NEW
  purchasedBundles?: string[]; // New field
  bonusClaimed?: boolean;
  nextBonusClaimTime?: number; // New: Timestamp for next daily bonus
  starterPackPurchased?: boolean;
  unlockedPack2?: string[]; // Array of difficulty names where Pack 2 (levels 101-200) is unlocked
  unlockedPack3?: string[]; // Array of difficulty names where Pack 3 (levels 201-300) is unlocked
}

export type DiamondOffer = {
  id: string;
  title: string;
  subtitle?: string;
  diamonds: number;
  includes?: string[];
  badge?: string;
  priceLabel: string;
  type: "starter" | "pack" | "bundle";
  gradientClass?: string;
};

import { AppSettings, LevelProgress, StoredData } from '../types';
import { Preferences } from '@capacitor/preferences';

const STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  sound: true,
  highlight: true,
  autoEraseNotes: true, // Default ON
  vibration: true,
  showTimer: true,
  appearance: 'light',
  digitFirst: false, // Default OFF
  screenWakeLock: false, // Default OFF
  generateReplay: false, // Default OFF
};

function getStoredData(): StoredData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      const initialData: StoredData = { 
          settings: DEFAULT_SETTINGS, 
          points: 0,
          progress: {},
          purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
          selectedBackground: 'bg-default',
          purchasedNumberColors: ['num-default'],
          selectedNumberColor: 'num-default',
          purchasedSkills: [],
          enabledSkills: [],
          purchasedSoundPacks: ['snd-zen'],
          selectedSoundPack: 'snd-zen',
          purchasedBundles: [],
          bonusClaimed: false,
          nextBonusClaimTime: 0,
          starterPackPurchased: false,
          unlockedPack2: [],
          unlockedPack3: [],
      };

      return initialData;
    }
    const data = JSON.parse(raw);

    // Migrations
    if (typeof data.points !== 'number') data.points = 0;

    if (!data.purchasedBackgrounds) data.purchasedBackgrounds = ['bg-default', 'bg-dyn-default'];
    if (!data.purchasedBackgrounds.includes('bg-default')) data.purchasedBackgrounds.push('bg-default');
    if (!data.purchasedBackgrounds.includes('bg-dyn-default')) data.purchasedBackgrounds.push('bg-dyn-default');

    if (data.selectedBackground === undefined) data.selectedBackground = 'bg-default';

    if (!data.purchasedNumberColors) data.purchasedNumberColors = ['num-default'];
    if (!data.selectedNumberColor) data.selectedNumberColor = 'num-default';

    if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
    if (!data.selectedSoundPack) data.selectedSoundPack = 'snd-zen';

    if (data.settings.vibration === undefined) data.settings.vibration = true;

    if (data.settings.showTimer === undefined) {
        if ((data.settings as any).hideTimer !== undefined) {
            data.settings.showTimer = !(data.settings as any).hideTimer;
            delete (data.settings as any).hideTimer;
        } else {
            data.settings.showTimer = true;
        }
    }

    if (data.settings.autoEraseNotes === undefined) data.settings.autoEraseNotes = true;
    if (data.settings.digitFirst === undefined) data.settings.digitFirst = false;
    if (data.settings.screenWakeLock === undefined) data.settings.screenWakeLock = false;
    if (data.settings.generateReplay === undefined) data.settings.generateReplay = false;

    if (data.settings.appearance === undefined) {
        data.settings.appearance = 'light'; 
    }

    if (!data.purchasedSkills) data.purchasedSkills = [];
    if (!data.enabledSkills) data.enabledSkills = [...data.purchasedSkills]; // Default new field to existing purchased skills
    if (!data.purchasedBundles) data.purchasedBundles = [];

    if (data.bonusClaimed === undefined) data.bonusClaimed = false;
    if (data.nextBonusClaimTime === undefined) data.nextBonusClaimTime = 0;

    if (data.starterPackPurchased === undefined) data.starterPackPurchased = false;

    if (!data.unlockedPack2) data.unlockedPack2 = [];
    if (!data.unlockedPack3) data.unlockedPack3 = [];

    return data;
  } catch (e) {
    console.error("Failed to load data", e);
    return { 
        settings: DEFAULT_SETTINGS, 
        points: 0, 
        progress: {},
        purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
        selectedBackground: 'bg-default',
        purchasedNumberColors: ['num-default'],
        selectedNumberColor: 'num-default',
        purchasedSkills: [],
        enabledSkills: [],
        purchasedSoundPacks: ['snd-zen'],
        selectedSoundPack: 'snd-zen',
        purchasedBundles: [],
        bonusClaimed: false,
        nextBonusClaimTime: 0,
        starterPackPurchased: false,
        unlockedPack2: [],
        unlockedPack3: [],
    };
  }
}

function saveData(data: StoredData) {
  try {
    const stringified = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, stringified);
    Preferences.set({
        key: STORAGE_KEY,
        value: stringified
    }).catch(err => console.error("Native save failed", err));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getStoredData, 

  initializeNative: async (): Promise<StoredData | null> => {
      try {
          const { value } = await Preferences.get({ key: STORAGE_KEY });
          if (value) {
              localStorage.setItem(STORAGE_KEY, value);
              return JSON.parse(value);
          }
          return null;
      } catch (e) {
          console.warn("Could not read native prefs", e);
          return null;
      }
  },

  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getPoints: (): number => {
    return getStoredData().points;
  },

  addPoints: (amount: number) => {
    const data = getStoredData();
    data.points += amount;
    saveData(data);
    return data.points;
  },

  getPurchasedBackgrounds: (): string[] => {
      return getStoredData().purchasedBackgrounds;
  },

  getSelectedBackground: (): string | null => {
      return getStoredData().selectedBackground;
  },

  purchaseBackground: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedBackgrounds.includes(id)) {
          data.points -= cost;
          data.purchasedBackgrounds.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectBackground: (id: string | null) => {
      const data = getStoredData();
      data.selectedBackground = id;
      saveData(data);
  },

  getPurchasedNumberColors: (): string[] => {
      return getStoredData().purchasedNumberColors;
  },

  getSelectedNumberColor: (): string => {
      return getStoredData().selectedNumberColor;
  },

  purchaseNumberColor: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedNumberColors.includes(id)) {
          data.points -= cost;
          data.purchasedNumberColors.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectNumberColor: (id: string) => {
      const data = getStoredData();
      data.selectedNumberColor = id;
      saveData(data);
  },

  getPurchasedSoundPacks: (): string[] => {
    return getStoredData().purchasedSoundPacks || ['snd-zen'];
  },

  getSelectedSoundPack: (): string => {
      return getStoredData().selectedSoundPack || 'snd-zen';
  },

  purchaseSoundPack: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
      if (data.points >= cost && !data.purchasedSoundPacks.includes(id)) {
          data.points -= cost;
          data.purchasedSoundPacks.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectSoundPack: (id: string) => {
      const data = getStoredData();
      data.selectedSoundPack = id;
      saveData(data);
  },

  getPurchasedSkills: (): string[] => {
      return getStoredData().purchasedSkills;
  },

  getEnabledSkills: (): string[] => {
    const data = getStoredData();
    return data.enabledSkills || [];
  },

  purchaseSkill: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedSkills.includes(id)) {
          data.points -= cost;
          data.purchasedSkills.push(id);
          if (!data.enabledSkills) data.enabledSkills = [];
          if (!data.enabledSkills.includes(id)) data.enabledSkills.push(id); // Auto enable on purchase
          saveData(data);
          return true;
      }
      return false;
  },

  toggleSkillEnabled: (id: string) => {
    const data = getStoredData();
    if (!data.enabledSkills) data.enabledSkills = [];
    if (data.enabledSkills.includes(id)) {
      data.enabledSkills = data.enabledSkills.filter(s => s !== id);
    } else if (data.purchasedSkills.includes(id)) {
      data.enabledSkills.push(id);
    }
    saveData(data);
    return data.enabledSkills;
  },

  getPurchasedBundles: (): string[] => {
      return getStoredData().purchasedBundles || [];
  },

  purchaseBundle: (id: string) => {
      const data = getStoredData();
      if (!data.purchasedBundles) data.purchasedBundles = [];
      if (!data.purchasedBundles.includes(id)) {
          data.purchasedBundles.push(id);
          saveData(data);
      }
  },

  isBonusClaimed: (): boolean => {
      return !!getStoredData().bonusClaimed;
  },

  setBonusClaimed: () => {
      const data = getStoredData();
      data.bonusClaimed = true;
      saveData(data);
  },

  getNextBonusClaimTime: (): number => {
      return getStoredData().nextBonusClaimTime || 0;
  },

  setNextBonusClaimTime: (time: number) => {
      const data = getStoredData();
      data.nextBonusClaimTime = time;
      saveData(data);
  },

  isStarterPackPurchased: (): boolean => {
      return !!getStoredData().starterPackPurchased;
  },

  setStarterPackPurchased: () => {
      const data = getStoredData();
      data.starterPackPurchased = true;
      saveData(data);
  },

  getUnlockedPacks2: (): string[] => {
      return getStoredData().unlockedPack2 || [];
  },

  isPack2Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack2?.includes(difficulty) ?? false;
  },

  unlockPack2: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack2) data.unlockedPack2 = [];

      if (data.points >= cost && !data.unlockedPack2.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack2.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getUnlockedPacks3: (): string[] => {
      return getStoredData().unlockedPack3 || [];
  },

  isPack3Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack3?.includes(difficulty) ?? false;
  },

  unlockPack3: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack3) data.unlockedPack3 = [];

      if (data.points >= cost && !data.unlockedPack3.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack3.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    const existing = data.progress[key];
    let bestTime = existing?.bestTime;
    if (progress.status === 'completed') {
        if (bestTime === undefined || progress.timeElapsed < bestTime) {
            bestTime = progress.timeElapsed;
        }
    }
    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };
    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];
           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1 
           };
           saveData(data);
      }
  },

  resetAllData: () => {
    localStorage.removeItem(STORAGE_KEY);
    Preferences.remove({ key: STORAGE_KEY }).catch(() => {});
  },

  getCompletedCount: (difficulty: string, maxLevel: number = 200): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  getCompletedCountInRange: (difficulty: string, minLevel: number, maxLevel: number): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId >= minLevel && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string, silent: boolean = false) => {
        e.stopPropagation();
        if (!silent) sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                // When clicking an already selected sound pack, make the tooltip call silent
                handleItemTooltip(e, pack.id, true);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-7 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[15px] font-black text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        // Skills still need a toggle footer
        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className={`h-8 border-t flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-all ${skillEnabled ? 'border-transparent bg-transparent' : 'border-t-border bg-white dark:bg-stone-800'}`}
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        // For backgrounds, sounds, and numbers: remove footer entirely once bought
        return null;
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={onBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isPurchased && isEnabled ? 'border-blue-500 scale-105 z-10' : 'border-t-border active:scale-95'} ${isPurchased && !isEnabled ? 'opacity-60 grayscale' : 'bg-t-surface'}`}
                                              >
                                                  <div className={`flex-1 flex items-center justify-center ${skill.bgClass}`}>
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>
                                                  <ItemFooter 
                                                      isPurchased={isPurchased} 
                                                      isSkill={true} 
                                                      skillEnabled={isEnabled} 
                                                      cost={skill.cost} 
                                                      onToggle={(e: any) => handleToggleClick(e, skill.id)}
                                                  />
                                              </button>
                                          </div>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
