                        <button 
                            onClick={handleToggleMenu}
                            className="w-full bg-t-surface p-4 rounded-2xl shadow-sm border border-t-border flex items-center justify-between active:scale-[0.98] transition-all relative z-10"
                        >
                            <span className="text-lg font-bold text-t-primary">{selectedDiff}</span>
                            <Icons.Back className={`w-5 h-5 text-t-secondary transition-transform duration-300 ${isDiffMenuOpen ? '-rotate-90' : '-rotate-180'}`} /> 
                        </button>

                        {/* Accordion Content */}
                        <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isDiffMenuOpen ? 'max-h-[400px] opacity-100 mt-2' : 'max-h-0 opacity-0 mt-0'}`}>
                            <div className="bg-t-surface rounded-2xl shadow-sm border border-t-border overflow-hidden flex flex-col">
                                {Object.values(Difficulty).map((diff) => (
                                    <button
                                        key={diff}
                                        onClick={() => handleSelectDiff(diff)}
                                        className={`w-full text-left px-5 py-4 text-lg font-bold border-b border-t-border last:border-0 hover:bg-stone-50 dark:hover:bg-stone-800 transition-colors ${selectedDiff === diff ? 'text-blue-500 bg-blue-50/50 dark:bg-blue-900/10' : 'text-t-primary'}`}
                                    >
                                        {diff}
