import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string, silent: boolean = false) => {
        e.stopPropagation();
        if (!silent) sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                // When clicking an already selected sound pack, make the tooltip call silent
                handleItemTooltip(e, pack.id, true);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-7 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[15px] font-bold text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        // Skills still need a toggle footer
        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className={`h-8 border-t flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-all ${skillEnabled ? 'border-transparent bg-transparent' : 'border-t-border bg-white dark:bg-stone-800'}`}
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        // For backgrounds, sounds, and numbers: remove footer entirely once bought
        return null;
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             {/* Locked Header */}
             <div className="w-full max-w-md flex items-start px-6 pb-4 relative shrink-0 z-20 pt-[120px]">
                <button onClick={onBack} className="absolute left-6 top-[70px] p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>
                 <div className="absolute right-6 top-[70px] flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                  </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col items-center text-center mt-2 mb-6">
                           <h1 className="text-2xl font-bold text-t-primary text-center">Store</h1>
                           <p className="text-t-secondary text-sm font-medium mt-1">Personalize your journey</p>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isPurchased && isEnabled ? 'border-blue-500 scale-105 z-10' : 'border-t-border active:scale-95'} ${isPurchased && !isEnabled ? 'opacity-60 grayscale' : 'bg-t-surface'}`}
                                              >
                                                  <div className={`flex-1 flex items-center justify-center ${skill.bgClass}`}>
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>
                                                  <ItemFooter 
                                                      isPurchased={isPurchased} 
                                                      isSkill={true} 
                                                      skillEnabled={isEnabled} 
                                                      cost={skill.cost} 
                                                      onToggle={(e: any) => handleToggleClick(e, skill.id)}
                                                  />
                                              </button>
                                          </div>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-100`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center w-full ${num.bgClass}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { getDifficultyPoints } from '../../utils/constants';

interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
}

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore,
    onOpenDiamondShop,
    onClaimBonus,
    onOpenStats,
    nextBonusClaimTime
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
             {/* Fixed Header */}
             <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                  <div className="flex flex-col items-start">
                      <h1 className="text-xl font-bold leading-none text-t-primary">Oku: Sudoku</h1>
                      <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Difficulty</p>
                  </div>
                  <div className="flex items-center gap-2">
                      <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                          <span className="text-sm font-bold text-t-primary">{points}</span>
                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                      </div>
                      <button onClick={() => { sounds.playClick(); onOpenSettings(); }} className="p-2 bg-t-surface rounded-full shadow-sm border border-t-border hover:shadow-md transition active:scale-95">
                          <Icons.Settings className="w-5 h-5 text-t-icon" />
                      </button>
                  </div>
             </div>

             {/* Scrollable Content */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-6 shrink-0 pt-2">
                      {Object.values(Difficulty).map((diff) => {
                          const completed = Storage.getCompletedCount(diff, 300); // Check all possible levels
                          // Logic to derive maxLevels for display
                          const isPack2Unlocked = Storage.isPack2Unlocked(diff);
                          const isPack3Unlocked = Storage.isPack3Unlocked(diff);

                          let maxLevels = 100;
                          if (isPack2Unlocked) maxLevels = 200;
                          if (isPack3Unlocked) maxLevels = 300;

                          const diffPoints = getDifficultyPoints(diff);
                          return (
                              <button key={diff} onClick={() => onDifficultySelect(diff)} className="bg-t-surface p-5 rounded-2xl shadow-sm border border-t-border flex flex-col items-start gap-1 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left relative overflow-hidden">
                                  <div className="w-full flex justify-between items-start">
                                      <span className="text-lg font-bold text-t-primary leading-tight">{diff}</span>
                                      <div className="flex items-center gap-1 ml-2 shrink-0">
                                          <span className="text-sm font-bold text-t-primary">+{diffPoints}</span>
                                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                      </div>
                                  </div>
                                  <span className="text-sm text-t-secondary font-medium tracking-wide mt-1">{completed} / {maxLevels}</span>
                                  <div className="w-full h-1 bg-t-surface-sec rounded-full mt-2 overflow-hidden">
                                      <div className="h-full bg-stone-600" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                  </div>
                              </button>
                          )
                      })}
                  </div>

                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      <div className="grid grid-cols-2 gap-3">
                          <button onClick={() => { sounds.playClick(); onOpenStore(); }} className="w-full p-4 btn-store-brown rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition relative">
                              <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                          </button>
                          <button onClick={() => { sounds.playClick(); onOpenDiamondShop(); }} className="w-full p-4 btn-premium-blue text-stone-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition overflow-hidden relative">
                              <span className="font-bold tracking-wide relative z-10">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10" />
                          </button>
                      </div>

                      <div className="grid grid-cols-2 gap-3">
                          {/* Stats Button */}
                          <button onClick={() => { sounds.playClick(); onOpenStats(); }} className="w-full p-4 bg-t-surface border border-t-border rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md">
                              <Icons.BarChart className="w-5 h-5 text-t-primary" /> <span className="font-bold tracking-wide text-t-primary">Stats</span>
                          </button>

                          {/* Daily Bonus Button */}
                          <button 
                              onClick={onClaimBonus} 
                              disabled={!!timeLeft}
                              className={`w-full p-4 border-2 rounded-2xl shadow-sm flex items-center justify-center gap-2 transition overflow-hidden relative ${!!timeLeft ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed' : 'bg-emerald-50 border-emerald-200 text-emerald-600 active:scale-95 hover:bg-emerald-100'}`}
                          >
                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-5 h-5" />
                                      <span className="font-bold text-sm tabular-nums">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-bold text-sm tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string, silent: boolean = false) => {
        e.stopPropagation();
        if (!silent) sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                // When clicking an already selected sound pack, make the tooltip call silent
                handleItemTooltip(e, pack.id, true);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-7 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[15px] font-bold text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        // Skills still need a toggle footer
        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className={`h-8 border-t flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-all ${skillEnabled ? 'border-transparent bg-transparent' : 'border-t-border bg-white dark:bg-stone-800'}`}
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        // For backgrounds, sounds, and numbers: remove footer entirely once bought
        return null;
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             {/* Locked Header */}
             <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Store</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Personalize</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border relative z-30">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-8 pt-2">

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isPurchased && isEnabled ? 'border-blue-500 scale-105 z-10' : 'border-t-border active:scale-95'} ${isPurchased && !isEnabled ? 'opacity-60 grayscale' : 'bg-t-surface'}`}
                                              >
                                                  <div className={`flex-1 flex items-center justify-center ${skill.bgClass}`}>
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>
                                                  <ItemFooter 
                                                      isPurchased={isPurchased} 
                                                      isSkill={true} 
                                                      skillEnabled={isEnabled} 
                                                      cost={skill.cost} 
                                                      onToggle={(e: any) => handleToggleClick(e, skill.id)}
                                                  />
                                              </button>
                                          </div>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-100`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 border-2 ${isSelected ? 'border-blue-500 scale-105 z-10' : 'border-t-border bg-t-surface'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center w-full ${num.bgClass}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className="text-sm font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

