                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-5 h-5" />
                                      <span className="font-bold tabular-nums">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-bold tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r) => saveProgress(b, s, r),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `sudoku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-[70px] pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
         />

         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={!!selectedCell && board[selectedCell[0]][selectedCell[1]].value !== null && !board[selectedCell[0]][selectedCell[1]].isFixed}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-sm font-light text-stone-400 dark:text-stone-500 tracking-wide">TAP HERE TO DESELECT</span>
         </div>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Crescendo feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C4 (~261Hz) to C6 (~1046Hz) based on progress
        const freq = 261.63 * Math.pow(4, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  // IMPORTANT: This relies on the user gesture chain not being broken by setTimeout upstream
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  // Try to resume if suspended (iOS requirement).
  if (audioCtx.state === 'suspended') {
      try {
        await Promise.race([
            audioCtx.resume(),
            new Promise((_, reject) => setTimeout(() => reject('timeout'), 200))
        ]);
      } catch (e) {
        // Proceeding without audio if resume fails
        console.warn('Audio resume failed', e);
      }
  }

  // Only add audio track if context is actually running.
  const useAudio = audioCtx.state === 'running';

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const MIN_FILL_MS = 2000;
  // Dynamic fill time based on move count (150ms per move), ensuring long puzzles render fully.
  const FILL_MS = Math.max(MIN_FILL_MS, moves.length * 150); 
  const INTRO_MS = 500; 
  const OUTRO_MS = 2000; 

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const availableFrames = Math.max(1, FILL_FRAMES - 5);

  for (let i = 0; i < moveCount; i++) {
      const progress = i / Math.max(1, moveCount - 1);
      moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableFrames);
  }

  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const drawLogo = (ctx: CanvasRenderingContext2D, x: number, y: number, s: number) => {
    // scale factor k = s / 100
    const k = s / 100;

    const drawRect = (lx: number, ly: number, color1: string, color2: string) => {
        const rx = x + lx * k;
        const ry = y + ly * k;
        const rw = 42 * k;
        const rh = 42 * k;
        const rr = 12 * k;

        const grad = ctx.createLinearGradient(rx, ry, rx + rw, ry + rh);
        grad.addColorStop(0, color1);
        grad.addColorStop(1, color2);

        ctx.fillStyle = grad;
        ctx.beginPath();
        // Fallback for browsers/environments that might not support roundRect (though most do)
        if (ctx.roundRect) {
            ctx.roundRect(rx, ry, rw, rh, rr);
        } else {
            ctx.rect(rx, ry, rw, rh); // Fallback to square if needed
        }
        ctx.fill();
    };

    // TL - Gold
    drawRect(5, 5, '#E8BA6E', '#B78B4D');
    // TR - Silver
    drawRect(53, 5, '#F0F0F0', '#C0C0C0');
    // BL - Blue
    drawRect(5, 53, '#B8D3F5', '#79A6E3');
    // BR - Green
    drawRect(53, 53, '#B8DBBE', '#8CB794');
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t);
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // Header
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // Timer
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // Watermark with Logo
      const watermarkText = "OKU: SUDOKU";
      const logoSize = 44;
      const logoSpacing = 16;

      ctx.font = '500 30px "Outfit", sans-serif';
      const textMetrics = ctx.measureText(watermarkText);
      const totalContentWidth = logoSize + logoSpacing + textMetrics.width;

      const contentStartX = (size - totalContentWidth) / 2;
      const contentCenterY = size - (padding / 2);

      // Draw Logo
      drawLogo(ctx, contentStartX, contentCenterY - (logoSize / 2), logoSize);

      // Draw Text
      ctx.textAlign = 'left';
      ctx.fillStyle = c.watermark;
      ctx.fillText(watermarkText, contentStartX + logoSize + logoSpacing, contentCenterY + 2);

      // Board Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      // Use roundRect if available, polyfill/rect if not
      if (ctx.roundRect) {
         ctx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         ctx.rect(startX, startY, boardSize, boardSize);
      }
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Grid
      ctx.save();
      ctx.beginPath();
      if (ctx.roundRect) {
         ctx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         ctx.rect(startX, startY, boardSize, boardSize);
      }
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Numbers
      ctx.textAlign = 'center'; // Reset alignment for numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];
              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 5) numScale = 1.0 + (0.5 * (1 - (age / 5)));

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const alpha = Math.min(1, outroAge / 10);
          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;
          ctx.beginPath();
          if (ctx.roundRect) {
             ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          } else {
             ctx.rect(startX - 2, startY - 2, boardSize + 4, boardSize + 4);
          }
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  if (useAudio) {
      // Correct way to get track from stream destination
      const audioTrack = dest.stream.getAudioTracks()[0];
      if (audioTrack) {
          stream.addTrack(audioTrack);
      }
  }

  // Prioritize video/mp4 for iOS Safari
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', 
    'video/mp4',
    'video/webm; codecs=vp9', 
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 2500000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timer
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') mediaRecorder.stop();
  }, TOTAL_DURATION_MS + 4000);

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // Start Recording
  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  // Schedule Audio (only if enabled)
  const startTime = audioCtx.currentTime;
  if (useAudio) {
      for (let i = 0; i < moveCount; i++) {
          const timeOffset = moveFrames[i] / FPS; 
          playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
      }
      const victoryTime = (INTRO_FRAMES + FILL_FRAMES) / FPS;
      playVictory(startTime + victoryTime + 0.05);
  }

  // Visual Loop (Decoupled)
  const startWallTime = performance.now();
  const render = () => {
      try {
          const now = performance.now();
          const elapsed = (now - startWallTime) / 1000;
          const currentFrame = Math.floor(elapsed * FPS);

          if (currentFrame > TOTAL_FRAMES + 3) { 
              if (mediaRecorder.state === 'recording') mediaRecorder.stop();
              return;
          }

          drawBoard(currentFrame);
          requestAnimationFrame(render);
      } catch (e) {
          console.error("Render loop error", e);
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
      }
  };
  requestAnimationFrame(render);

  return recordingPromise;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(0);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          scanUses,
          revealUses
      });

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation (might not have gesture context here if async, but handled gracefully)
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard) => saveProgress(newBoard),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r) => saveProgress(b, s, r),
      onSectionComplete: handleSectionComplete
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState);
          setInitialTime(progress.timeElapsed);
          setTimer(progress.timeElapsed); 
      } else {
          initializeBoard();
          setInitialTime(0);
          setTimer(0); 
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard]);

  useEffect(() => {
    if (savedProgress) {
      if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
      if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
    } else {
      setScanUses(3);
      setRevealUses(1);
    }
  }, [difficulty, levelId]);

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves (e.g. reload), reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            // Row-by-row fill
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `sudoku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Minimal Sudoku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleDebugWin = () => {
      const newBoard: Board = board.map((row, r) => 
          row.map((cell, c) => ({
              ...cell,
              value: solvedBoard[r][c] as any,
              notes: [],
              isError: false
          }))
      );
      setBoard(newBoard);
      handleGameComplete(newBoard);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-[70px] pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-t-secondary uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <SudokuGrid 
             board={board}
             selectedCell={selectedCell}
             activeNumber={activeNumber}
             conflicts={conflicts}
             revealingCell={revealingCell}
             animatingCell={animatingCell}
             isScanning={isScanning}
             animatingSections={animatingSections}
             settings={settings}
             numberColor={numberColor}
             onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
         />

         <div className="w-full max-w-md px-6 mt-4 flex flex-col gap-6" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={!!selectedCell && board[selectedCell[0]][selectedCell[1]].value !== null && !board[selectedCell[0]][selectedCell[1]].isFixed}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
             />

             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
         </div>

         <div className={`mt-5 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-sm font-light text-stone-400 dark:text-stone-500 tracking-wide">TAP HERE TO DESELECT</span>
         </div>

         <button 
             onClick={(e) => { e.stopPropagation(); handleDebugWin(); }}
             className="mb-6 px-6 py-3 bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-200 dark:hover:bg-red-900/50 transition-colors"
         >
             Auto Solve (Debug)
         </button>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Crescendo feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 (~523Hz) to C7 (~2093Hz) based on progress
        // Started higher as requested (was C4)
        const freq = 523.25 * Math.pow(4, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  // IMPORTANT: This relies on the user gesture chain not being broken by setTimeout upstream
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  // Try to resume if suspended (iOS requirement).
  if (audioCtx.state === 'suspended') {
      try {
        await Promise.race([
            audioCtx.resume(),
            new Promise((_, reject) => setTimeout(() => reject('timeout'), 200))
        ]);
      } catch (e) {
        // Proceeding without audio if resume fails
        console.warn('Audio resume failed', e);
      }
  }

  // Only add audio track if context is actually running.
  const useAudio = audioCtx.state === 'running';

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const MIN_FILL_MS = 2000;
  const INTRO_MS = 500; 
  const OUTRO_MS = 2000; 

  // Target max total duration ~8 seconds
  const TARGET_TOTAL_MS = 8000;
  const MAX_FILL_MS = TARGET_TOTAL_MS - INTRO_MS - OUTRO_MS; // 5500ms

  // Dynamic fill time: 
  // Base rate 100ms per move (faster than before), but clamped to ensure we don't exceed ~8s total video
  const FILL_MS = Math.min(MAX_FILL_MS, Math.max(MIN_FILL_MS, moves.length * 100));

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const availableFrames = Math.max(1, FILL_FRAMES - 5);

  for (let i = 0; i < moveCount; i++) {
      const progress = i / Math.max(1, moveCount - 1);
      moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableFrames);
  }

  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const drawLogo = (ctx: CanvasRenderingContext2D, x: number, y: number, s: number) => {
    // scale factor k = s / 100
    const k = s / 100;

    const drawRect = (lx: number, ly: number, color1: string, color2: string) => {
        const rx = x + lx * k;
        const ry = y + ly * k;
        const rw = 42 * k;
        const rh = 42 * k;
        const rr = 12 * k;

        const grad = ctx.createLinearGradient(rx, ry, rx + rw, ry + rh);
        grad.addColorStop(0, color1);
        grad.addColorStop(1, color2);

        ctx.fillStyle = grad;
        ctx.beginPath();
        // Fallback for browsers/environments that might not support roundRect (though most do)
        if (ctx.roundRect) {
            ctx.roundRect(rx, ry, rw, rh, rr);
        } else {
            ctx.rect(rx, ry, rw, rh); // Fallback to square if needed
        }
        ctx.fill();
    };

    // TL - Gold
    drawRect(5, 5, '#E8BA6E', '#B78B4D');
    // TR - Silver
    drawRect(53, 5, '#F0F0F0', '#C0C0C0');
    // BL - Blue
    drawRect(5, 53, '#B8D3F5', '#79A6E3');
    // BR - Green
    drawRect(53, 53, '#B8DBBE', '#8CB794');
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t);
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // Header
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // Timer
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // Watermark with Logo
      const watermarkText = "OKU: SUDOKU";
      const logoSize = 44;
      const logoSpacing = 16;

      ctx.font = '500 30px "Outfit", sans-serif';
      const textMetrics = ctx.measureText(watermarkText);
      const totalContentWidth = logoSize + logoSpacing + textMetrics.width;

      const contentStartX = (size - totalContentWidth) / 2;
      const contentCenterY = size - (padding / 2);

      // Draw Logo
      drawLogo(ctx, contentStartX, contentCenterY - (logoSize / 2), logoSize);

      // Draw Text
      ctx.textAlign = 'left';
      ctx.fillStyle = c.watermark;
      ctx.fillText(watermarkText, contentStartX + logoSize + logoSpacing, contentCenterY + 2);

      // Board Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      // Use roundRect if available, polyfill/rect if not
      if (ctx.roundRect) {
         ctx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         ctx.rect(startX, startY, boardSize, boardSize);
      }
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Grid
      ctx.save();
      ctx.beginPath();
      if (ctx.roundRect) {
         ctx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         ctx.rect(startX, startY, boardSize, boardSize);
      }
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Numbers
      ctx.textAlign = 'center'; // Reset alignment for numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];
              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 5) numScale = 1.0 + (0.5 * (1 - (age / 5)));

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const alpha = Math.min(1, outroAge / 10);
          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;
          ctx.beginPath();
          if (ctx.roundRect) {
             ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          } else {
             ctx.rect(startX - 2, startY - 2, boardSize + 4, boardSize + 4);
          }
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  if (useAudio) {
      // Correct way to get track from stream destination
      const audioTrack = dest.stream.getAudioTracks()[0];
      if (audioTrack) {
          stream.addTrack(audioTrack);
      }
  }

  // Prioritize video/mp4 for iOS Safari
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', 
    'video/mp4',
    'video/webm; codecs=vp9', 
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 2500000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timer
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') mediaRecorder.stop();
  }, TOTAL_DURATION_MS + 4000);

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // Start Recording
  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      try { audioCtx.close(); } catch {}
      return null;
  }

  // Schedule Audio (only if enabled)
  const startTime = audioCtx.currentTime;
  if (useAudio) {
      for (let i = 0; i < moveCount; i++) {
          const timeOffset = moveFrames[i] / FPS; 
          playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
      }
      const victoryTime = (INTRO_FRAMES + FILL_FRAMES) / FPS;
      playVictory(startTime + victoryTime + 0.05);
  }

  // Visual Loop (Decoupled)
  const startWallTime = performance.now();
  const render = () => {
      try {
          const now = performance.now();
          const elapsed = (now - startWallTime) / 1000;
          const currentFrame = Math.floor(elapsed * FPS);

          if (currentFrame > TOTAL_FRAMES + 3) { 
              if (mediaRecorder.state === 'recording') mediaRecorder.stop();
              return;
          }

          drawBoard(currentFrame);
          requestAnimationFrame(render);
      } catch (e) {
          console.error("Render loop error", e);
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
      }
  };
  requestAnimationFrame(render);

  return recordingPromise;
}

