export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  // Reduced resolution to 720p for better mobile stability/compatibility
  const size = 720;
  const padding = 80; // Scaled down padding

  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  // Try to resume if suspended (iOS requirement).
  if (audioCtx.state === 'suspended') {
      try {
        await Promise.race([
            audioCtx.resume(),
            new Promise((_, reject) => setTimeout(() => reject('timeout'), 200))
        ]);
      } catch (e) {
        console.warn('Audio resume failed', e);
      }
  }

  // Only add audio track if context is actually running.
  const useAudio = audioCtx.state === 'running';

  const dest = audioCtx.createMediaStreamDestination();

  // IOS FIX: Add constant silent signal to keep the audio track active.
  // Without this, iOS MediaRecorder often drops the file or freezes if audio is sparse.
  let silentOsc: OscillatorNode | null = null;
  if (useAudio) {
      silentOsc = audioCtx.createOscillator();
      const silentGain = audioCtx.createGain();
      silentGain.gain.value = 0; // Absolute silence
      silentOsc.connect(silentGain);
      silentGain.connect(dest);
      silentOsc.start();
  }

  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const MIN_FILL_MS = 2000;
  const INTRO_MS = 500; 
  const OUTRO_MS = 2000; 

  // Target max total duration ~8 seconds
  const TARGET_TOTAL_MS = 8000;
  const MAX_FILL_MS = TARGET_TOTAL_MS - INTRO_MS - OUTRO_MS; 

  // Dynamic fill time
  const FILL_MS = Math.min(MAX_FILL_MS, Math.max(MIN_FILL_MS, moves.length * 100));

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);
  const availableFrames = Math.max(1, FILL_FRAMES - 5);

  for (let i = 0; i < moveCount; i++) {
      const progress = i / Math.max(1, moveCount - 1);
      moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableFrames);
  }

  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const drawLogo = (targetCtx: CanvasRenderingContext2D, x: number, y: number, s: number) => {
    const k = s / 100;

    const drawRect = (lx: number, ly: number, color1: string, color2: string) => {
        const rx = x + lx * k;
        const ry = y + ly * k;
        const rw = 42 * k;
        const rh = 42 * k;
        const rr = 12 * k;

        const grad = targetCtx.createLinearGradient(rx, ry, rx + rw, ry + rh);
        grad.addColorStop(0, color1);
        grad.addColorStop(1, color2);

        targetCtx.fillStyle = grad;
        targetCtx.beginPath();
        if (targetCtx.roundRect) {
            targetCtx.roundRect(rx, ry, rw, rh, rr);
        } else {
            targetCtx.rect(rx, ry, rw, rh);
        }
        targetCtx.fill();
    };

    drawRect(5, 5, '#E8BA6E', '#B78B4D');
    drawRect(53, 5, '#F0F0F0', '#C0C0C0');
    drawRect(5, 53, '#B8D3F5', '#79A6E3');
    drawRect(53, 53, '#B8DBBE', '#8CB794');
  };

  // --- OPTIMIZATION: STATIC CANVAS LAYER ---
  const staticCanvas = document.createElement('canvas');
  staticCanvas.width = size;
  staticCanvas.height = size;
  const staticCtx = staticCanvas.getContext('2d');

  if (staticCtx) {
      // 1. Background
      staticCtx.fillStyle = c.bg;
      staticCtx.fillRect(0, 0, size, size);

      // 2. Header
      staticCtx.textAlign = 'center';
      staticCtx.textBaseline = 'middle';
      staticCtx.fillStyle = c.textFixed;
      staticCtx.font = 'bold 32px "Outfit", sans-serif'; // Reduced font size for 720p
      const titleY = padding / 2;
      staticCtx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 10);

      // 3. Watermark
      const watermarkText = "OKU: SUDOKU";
      const logoSize = 36; // Reduced
      const logoSpacing = 12;
      staticCtx.font = '500 24px "Outfit", sans-serif'; // Reduced
      const textMetrics = staticCtx.measureText(watermarkText);
      const totalContentWidth = logoSize + logoSpacing + textMetrics.width;
      const contentStartX = (size - totalContentWidth) / 2;
      const contentCenterY = size - (padding / 2);

      drawLogo(staticCtx, contentStartX, contentCenterY - (logoSize / 2), logoSize);

      staticCtx.textAlign = 'left';
      staticCtx.fillStyle = c.watermark;
      staticCtx.fillText(watermarkText, contentStartX + logoSize + logoSpacing, contentCenterY + 2);

      // 4. Board Base
      staticCtx.shadowColor = "rgba(0,0,0,0.1)";
      staticCtx.shadowBlur = 20;
      staticCtx.shadowOffsetY = 6;
      staticCtx.fillStyle = c.boardBg;
      const r = 24; // Reduced radius
      staticCtx.beginPath();
      if (staticCtx.roundRect) {
         staticCtx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         staticCtx.rect(startX, startY, boardSize, boardSize);
      }
      staticCtx.fill();
      staticCtx.shadowBlur = 0;
      staticCtx.shadowOffsetY = 0;

      // 5. Grid
      staticCtx.save();
      staticCtx.beginPath();
      if (staticCtx.roundRect) {
         staticCtx.roundRect(startX, startY, boardSize, boardSize, r);
      } else {
         staticCtx.rect(startX, startY, boardSize, boardSize);
      }
      staticCtx.clip();

      staticCtx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          staticCtx.lineWidth = isThick ? 4 : 1.5; // Reduced thickness
          staticCtx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          staticCtx.beginPath();
          staticCtx.moveTo(startX + pos, startY);
          staticCtx.lineTo(startX + pos, startY + boardSize);
          staticCtx.stroke();

          staticCtx.beginPath();
          staticCtx.moveTo(startX, startY + pos);
          staticCtx.lineTo(startX + boardSize, startY + pos);
          staticCtx.stroke();
      }
      staticCtx.restore();

      // 6. Fixed Numbers
      staticCtx.textAlign = 'center';
      staticCtx.textBaseline = 'middle';
      staticCtx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      staticCtx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  staticCtx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });
  }

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Clear main canvas
      ctx.clearRect(0, 0, size, size);

      // Intro Logic
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t);
      }

      // 1. Draw Static Layer
      if (staticCtx) {
          ctx.save();
          ctx.globalAlpha = globalOpacity;
          ctx.drawImage(staticCanvas, 0, 0);
          ctx.restore();
      } else {
          ctx.fillStyle = c.bg;
          ctx.fillRect(0, 0, size, size);
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // 2. Draw Dynamic Timer
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 32px "Outfit", sans-serif'; // Reduced size
      const titleY = padding / 2;

      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 24);

      // 3. Draw Dynamic Moves
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];
              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 5) numScale = 1.0 + (0.5 * (1 - (age / 5)));

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // 4. Draw Outro Border
      if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          const outroAge = frame - (INTRO_FRAMES + FILL_FRAMES);
          const alpha = Math.min(1, outroAge / 10);
          const r = 24;

          ctx.lineWidth = 10;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;
          ctx.beginPath();
          if (ctx.roundRect) {
             ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          } else {
             ctx.rect(startX - 2, startY - 2, boardSize + 4, boardSize + 4);
          }
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  drawBoard(0);

  // Safely construct stream tracks for iOS
  const videoStream = canvas.captureStream(FPS);
  const tracks = [...videoStream.getVideoTracks()];

  if (useAudio) {
      const audioTrack = dest.stream.getAudioTracks()[0];
      if (audioTrack) {
          tracks.push(audioTrack);
      }
  }
  const combinedStream = new MediaStream(tracks);

  // Prioritize video/mp4 for iOS Safari
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', 
    'video/mp4',
    'video/webm; codecs=vp9', 
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      mediaRecorder = new MediaRecorder(combinedStream, { mimeType, videoBitsPerSecond: 2500000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      if (silentOsc) silentOsc.stop();
      try { audioCtx.close(); } catch {}
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') mediaRecorder.stop();
  }, TOTAL_DURATION_MS + 4000);

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);

      if (silentOsc) {
          try { silentOsc.stop(); } catch {}
      }
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        if (silentOsc) try { silentOsc.stop(); } catch {}
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  try {
      mediaRecorder.start();
  } catch (e) {
      console.error("MediaRecorder start failed", e);
      if (silentOsc) try { silentOsc.stop(); } catch {}
      try { audioCtx.close(); } catch {}
      return null;
  }

  // Schedule Audio
  const startTime = audioCtx.currentTime;
  if (useAudio) {
      for (let i = 0; i < moveCount; i++) {
          const timeOffset = moveFrames[i] / FPS; 
          playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
      }
      const victoryTime = (INTRO_FRAMES + FILL_FRAMES) / FPS;
      playVictory(startTime + victoryTime + 0.05);
  }

  const startWallTime = performance.now();
  const render = () => {
      try {
          const now = performance.now();
          const elapsed = (now - startWallTime) / 1000;
          const currentFrame = Math.floor(elapsed * FPS);

          if (currentFrame > TOTAL_FRAMES + 3) { 
              if (mediaRecorder.state === 'recording') mediaRecorder.stop();
              return;
          }

          drawBoard(currentFrame);
          requestAnimationFrame(render);
      } catch (e) {
          console.error("Render loop error", e);
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
      }
  };
  requestAnimationFrame(render);

  return recordingPromise;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  const savedProgress = Storage.getLevelProgress(difficulty, levelId);
  const [initialTime, setInitialTime] = useState(savedProgress?.timeElapsed || 0);

  // Refs to hold current skill uses to avoid circular dependencies in saveProgress
  const skillsRef = useRef({ scanUses: savedProgress?.scanUses ?? 3, revealUses: savedProgress?.revealUses ?? 1 });

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      initialTime
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : skillsRef.current.scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : skillsRef.current.revealUses
      });
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
          sounds.playZap();
      }
  }, []);

  const handleGameComplete = useCallback((completedBoard: Board) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1000);

      setIsCompleted(true);
      onComplete(); // Trigger parent point update if needed

      // Calculate points
      const diffPoints = difficulty === Difficulty.Impossible ? 50 : 
                         difficulty === Difficulty.Intense ? 30 :
                         difficulty === Difficulty.Hard ? 20 :
                         difficulty === Difficulty.Normal ? 15 :
                         difficulty === Difficulty.Easy ? 10 : 5;

      onEarnPoints(diffPoints);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          lastPlayed: Date.now(),
          bestTime: timer, // Logic handled in Storage.saveLevelProgress (min check)
          scanUses: skillsRef.current.scanUses,
          revealUses: skillsRef.current.revealUses
      });

  }, [difficulty, isCompleted, isEnding, levelId, onComplete, onEarnPoints, timer]);

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onBoardChange: (b) => saveProgress(b),
      onComplete: handleGameComplete,
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: saveProgress,
      onSectionComplete: handleSectionComplete
  });

  // Keep refs updated
  useEffect(() => {
      skillsRef.current = { scanUses, revealUses };
  }, [scanUses, revealUses]);

  // Initialize from storage or new
  useEffect(() => {
      if (savedProgress?.boardState && savedProgress.status === 'in-progress') {
          initializeBoard(savedProgress.boardState);
          setScanUses(savedProgress.scanUses ?? 3);
          setRevealUses(savedProgress.revealUses ?? 1);
      } else {
          initializeBoard();
      }
      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 3000);
  }, [initializeBoard]); // eslint-disable-line

  const handleGenerateReplay = async () => {
      setIsGeneratingReplay(true);
      try {
          const isDark = document.documentElement.classList.contains('dark');
          const url = await generateReplayVideo(
              initialBoardRef.current,
              moveLog.current,
              difficulty,
              levelId,
              isDark,
              timer
          );
          setReplayUrl(url);
          setShowReplay(true);
      } catch (e) {
          console.error("Replay generation failed", e);
      } finally {
          setIsGeneratingReplay(false);
      }
  };

  return (
    <div className={`w-full h-full flex flex-col items-center relative overflow-hidden ${isCompleted ? 'pointer-events-none' : ''}`}>

        {/* Header */}
        <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-2 z-20 shrink-0">
             <button onClick={onBack} className="p-2 -ml-2 text-t-icon rounded-full hover:bg-stone-200/50 transition">
                 <Icons.Back className="w-6 h-6" />
             </button>

             <div className="flex flex-col items-center">
                 <span className="text-[10px] font-bold tracking-widest uppercase text-t-secondary">{difficulty}</span>
                 <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
             </div>

             <button onClick={onSettingsOpen} className="p-2 -mr-2 text-t-icon rounded-full hover:bg-stone-200/50 transition">
                 <Icons.Settings className="w-6 h-6" />
             </button>
        </div>

        {/* Info Bar */}
        <div className="w-full max-w-md flex items-center justify-between px-8 py-2 mb-2 z-20 shrink-0">
             <div className="flex items-center gap-2">
                 <Icons.Clock className="w-4 h-4 text-t-secondary" />
                 <span className="text-lg font-bold text-t-primary tabular-nums tracking-tight">
                    {settings.showTimer ? formatTimeShort(timer) : '--:--'}
                 </span>
             </div>
             <div className="flex items-center gap-1.5">
                  {/* Mistakes could go here */}
             </div>
        </div>

        {/* Board Area */}
        <div className="flex-1 w-full flex flex-col items-center justify-center relative min-h-0">
             <SudokuGrid 
                board={board}
                selectedCell={selectedCell}
                activeNumber={activeNumber}
                conflicts={conflicts}
                revealingCell={revealingCell}
                animatingCell={animatingCell}
                isScanning={isScanning}
                animatingSections={animatingSections}
                settings={settings}
                numberColor={numberColor}
                onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
             />

             {/* Hint Overlay */}
             {showStartHint && !isCompleted && (
                 <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-stone-900/80 text-white px-3 py-1.5 rounded-full text-xs font-bold pointer-events-none animate-fade-out delay-1000">
                     Tap a cell to start
                 </div>
             )}
        </div>

        {/* Controls Area */}
        <div className="w-full max-w-md px-4 pb-8 pt-2 z-20 shrink-0 flex flex-col gap-4">
             <GameControls 
                canUndo={history.length > 0}
                canErase={!!selectedCell && board[selectedCell[0]][selectedCell[1]].value !== null && !board[selectedCell[0]][selectedCell[1]].isFixed}
                isPencilMode={isPencilMode}
                onUndo={(e) => handleUndo(isPaused, isCompleted)}
                onErase={(e) => handleErase(isPaused, isCompleted)}
                onTogglePencil={(e) => setIsPencilMode(!isPencilMode)}
                purchasedSkills={purchasedSkills}
                isAutoAvailable={isAutoAvailable}
                scanUses={scanUses}
                isScanning={isScanning}
                scanCooldown={scanCooldown}
                revealUses={revealUses}
                revealingCell={revealingCell}
                onAutoFill={(e) => handleAutoFill(purchasedSkills)}
                onScan={(e) => handleScan(isPaused, isCompleted)}
                onReveal={(e) => handleReveal(isPaused, isCompleted)}
             />

             <NumberPad 
                activeNumber={activeNumber}
                numberCounts={numberCounts}
                isPencilMode={isPencilMode}
                numberColor={numberColor}
                onNumberClick={(e, n) => handleNumberInput(n, isPaused, isCompleted)}
             />
        </div>

        {/* Win Modal Overlay */}
        {isEnding && (
            <WinModal 
                difficulty={difficulty}
                levelId={levelId}
                timer={timer}
                points={0} // passed from parent logic mainly
                isGeneratingReplay={isGeneratingReplay}
                replayUrl={replayUrl}
                showReplay={showReplay}
                generateReplayEnabled={settings.generateReplay}
                onReplay={() => setShowReplay(true)}
                onShareReplay={() => {
                    // Share logic
                    if (replayUrl && navigator.share) {
                        fetch(replayUrl).then(r => r.blob()).then(blob => {
                            const file = new File([blob], `oku-replay-${levelId}.webm`, { type: 'video/webm' });
                            navigator.share({
                                files: [file],
                                title: 'My Sudoku Replay',
                            }).catch(console.error);
                        });
                    }
                }}
                onCloseReplay={() => setShowReplay(false)}
                onGenerateReplay={handleGenerateReplay}
                onBack={onBack}
                onReturnToMenu={onReturnToMenu}
            />
        )}
    </div>
  );
};

import React, { useState, useMemo, SetStateAction, Dispatch, useCallback } from 'react';
import { Board, Difficulty, CellValue, AppSettings } from '../types';
import { sounds } from '../utils/sound';

interface UseGameSkillsProps {
    board: Board;
    setBoard: Dispatch<SetStateAction<Board>>;
    solvedBoard: number[][];
    setHistory: Dispatch<SetStateAction<Board[]>>;
    moveLog: React.MutableRefObject<{r: number, c: number, v: number, t: number}[]>;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    settings: AppSettings;
    difficulty: Difficulty;
    removeNotesFromPeers: (board: Board, r: number, c: number, val: number) => void;
    checkCompletion: (board: Board) => void;
    onSaveProgress: (board: Board, scanUses?: number, revealUses?: number) => void;
    onSectionComplete?: (sections: string[]) => void;
}

const checkSectionCompletion = (board: Board, solvedBoard: number[][], r: number, c: number) => {
    const sections: string[] = [];
    // Row
    if (board[r].every((cell, idx) => cell.value === solvedBoard[r][idx])) sections.push(`row-${r}`);
    // Col
    if (board.every((row, idx) => row[c].value === solvedBoard[idx][c])) sections.push(`col-${c}`);
    // Box
    const startR = Math.floor(r/3)*3;
    const startC = Math.floor(c/3)*3;
    const boxIdx = Math.floor(r/3)*3 + Math.floor(c/3);
    let boxOk = true;
    for(let i=0; i<3; i++) {
        for(let j=0; j<3; j++) {
            if(board[startR+i][startC+j].value !== solvedBoard[startR+i][startC+j]) {
                boxOk = false;
                break;
            }
        }
    }
    if (boxOk) sections.push(`box-${boxIdx}`);
    return sections;
};

export const useGameSkills = ({
    board,
    setBoard,
    solvedBoard,
    setHistory,
    moveLog,
    selectedCell,
    activeNumber,
    settings,
    difficulty,
    removeNotesFromPeers,
    checkCompletion,
    onSaveProgress,
    onSectionComplete
}: UseGameSkillsProps) => {

    const [scanUses, setScanUses] = useState(3);
    const [isScanning, setIsScanning] = useState(false);
    const [scanCooldown, setScanCooldown] = useState(false);
    const [revealUses, setRevealUses] = useState(1);
    const [revealingCell, setRevealingCell] = useState<{r: number, c: number} | null>(null);
    const [animatingCell, setAnimatingCell] = useState<{r: number, c: number, value: number} | null>(null);

    const isBoardComplete = useCallback((currentBoard: Board) => {
        if (solvedBoard.length === 0) return false;
        let filled = 0;
        let correct = 0;
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                if (currentBoard[r][c].value !== null) {
                    filled++;
                    if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
                }
            }
        }
        return filled === 81 && correct === 81;
    }, [solvedBoard]);

    const isAutoAvailable = useMemo(() => {
        if (!selectedCell || board.length === 0) return false;
        let r = selectedCell[0];
        let c = selectedCell[1];
        const cell = board[r][c];
        if (cell.value !== null || cell.isRevealed) return false;

        let rowCount = 0;
        for(let i=0; i<9; i++) if (board[r][i].value !== null) rowCount++;
        if (rowCount === 8) return true;

        let colCount = 0;
        for(let i=0; i<9; i++) if (board[i][c].value !== null) colCount++;
        if (colCount === 8) return true;

        let boxCount = 0;
        const startR = Math.floor(r/3)*3;
        const startC = Math.floor(c/3)*3;
        for(let i=0; i<3; i++)
            for(let j=0; j<3; j++)
                if (board[startR+i][startC+j].value !== null) boxCount++;
        if (boxCount === 8) return true;

        return false;
    }, [board, selectedCell]);

    const handleAutoFill = (purchasedSkills: string[]) => {
        if (!purchasedSkills.includes('skill-auto') || !isAutoAvailable || !selectedCell || isScanning || revealingCell) return;
        sounds.playZap(); 
        const [r, c] = selectedCell;

        let valToFill: number | null = null;

        const getMissing = (values: (number | null)[]) => {
            const vals = new Set(values.filter(v => v !== null));
            for (let i = 1; i <= 9; i++) if (!vals.has(i)) return i;
            return null;
        };

        if (board[r].filter(cell => cell.value !== null).length === 8) {
            valToFill = getMissing(board[r].map(c => c.value));
        }
        if (valToFill === null) {
            const colVals = board.map(row => row[c].value);
            if (colVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(colVals);
            }
        }
        if (valToFill === null) {
            const startR = Math.floor(r/3)*3;
            const startC = Math.floor(c/3)*3;
            const boxVals = [];
            for(let i=0; i<3; i++) for(let j=0; j<3; j++) boxVals.push(board[startR+i][startC+j].value);
            if (boxVals.filter(v => v !== null).length === 8) {
                valToFill = getMissing(boxVals);
            }
        }

        if (valToFill === null) valToFill = solvedBoard[r][c];

        const val = valToFill as number;
        setAnimatingCell({ r, c, value: 1 });
        setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
        const newBoard = board.map(row => [...row]);

        const isHarderDifficulty = difficulty === Difficulty.Hard || difficulty === Difficulty.Intense || difficulty === Difficulty.Impossible;
        const isCorrect = val === solvedBoard[r][c];

        newBoard[r][c] = {
            ...newBoard[r][c],
            value: val as any,
            notes: [],
            isError: !isHarderDifficulty ? !isCorrect : false,
            isMarkedWrong: false
        };

        moveLog.current.push({ r, c, v: val, t: Date.now() });

        if (settings.autoEraseNotes) {
             removeNotesFromPeers(newBoard, r, c, val);
        }

        setBoard(newBoard);
        onSaveProgress(newBoard, scanUses, revealUses);

        const isFinishingMove = isBoardComplete(newBoard);
        if (!newBoard[r][c].isError && !isFinishingMove) {
            const completedSections = checkSectionCompletion(newBoard, solvedBoard, r, c);
            if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
        }

        const startTime = performance.now();
        const duration = 300; 
        const animate = (time: number) => {
            const elapsed = time - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const currentVal = Math.floor(1 + (val - 1) * progress);
            setAnimatingCell({ r, c, value: currentVal });
            if (progress < 1) requestAnimationFrame(animate);
            else setAnimatingCell(null);
        };
        requestAnimationFrame(animate);
        checkCompletion(newBoard);
    };

    const handleScan = (isPaused: boolean, isCompleted: boolean) => {
        if (scanUses <= 0 || isScanning || scanCooldown || isPaused || isCompleted || revealingCell) return;
        setIsScanning(true);
        setScanCooldown(true);
        sounds.playScan();
        setTimeout(() => {
            const newBoard = board.map(row => row.map(cell => {
                if (!cell.isFixed && cell.value !== null) {
                    const isCorrect = cell.value === solvedBoard[cell.row][cell.col];
                    if (!isCorrect) return { ...cell, isMarkedWrong: true };
                }
                return cell;
            }));
            setBoard(newBoard);
            setIsScanning(false);
            setScanUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, next, revealUses);
                return next;
            });
            setTimeout(() => setScanCooldown(false), 1000); 
        }, 1200); 
    };

    const handleReveal = (isPaused: boolean, isCompleted: boolean) => {
        if (isPaused || isCompleted || revealingCell || isScanning) return;
        if (revealUses <= 0) {
            sounds.playClick();
            return;
        }

        const eligible = [];
        for(let r=0; r<9; r++) {
            for(let c=0; c<9; c++) {
                const cell = board[r][c];
                if (cell.value === null && !cell.isFixed && !cell.isRevealed) {
                    eligible.push({r, c});
                }
            }
        }
        if (eligible.length === 0) return;

        sounds.playReveal(); 
        const target = eligible[Math.floor(Math.random() * eligible.length)];
        setRevealingCell(target);

        setTimeout(() => {
            setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);
            const newBoard = board.map(row => [...row]);
            const correctVal = solvedBoard[target.r][target.c];

            newBoard[target.r][target.c] = {
                ...newBoard[target.r][target.c],
                value: correctVal as CellValue,
                notes: [],
                isFixed: false, 
                isRevealed: true, 
                isError: false,
                isMarkedWrong: false
            };

            moveLog.current.push({ r: target.r, c: target.c, v: correctVal, t: Date.now() });

            if (settings.autoEraseNotes) {
                 removeNotesFromPeers(newBoard, target.r, target.c, correctVal);
            }

            setBoard(newBoard);
            setRevealUses(prev => {
                const next = prev - 1;
                onSaveProgress(newBoard, scanUses, next);
                return next;
            });

            const isFinishingMove = isBoardComplete(newBoard);
            if (!isFinishingMove) {
                const completedSections = checkSectionCompletion(newBoard, solvedBoard, target.r, target.c);
                if (completedSections.length > 0 && onSectionComplete) onSectionComplete(completedSections);
            }

            setTimeout(() => {
                setRevealingCell(null);
                checkCompletion(newBoard);
            }, 300); 
        }, 500); 
    };

    return {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        handleAutoFill,
        handleScan,
        handleReveal
    };
};

import { AppSettings, LevelProgress, StoredData } from '../types';
import { Preferences } from '@capacitor/preferences';

const STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  sound: true,
  highlight: true,
  autoEraseNotes: true, // Default ON
  vibration: true,
  showTimer: true,
  appearance: 'light',
  digitFirst: false, // Default OFF
  screenWakeLock: false, // Default OFF
  generateReplay: true, // Default ON
};

function getStoredData(): StoredData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      const initialData: StoredData = { 
          settings: DEFAULT_SETTINGS, 
          points: 0,
          progress: {},
          purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
          selectedBackground: 'bg-default',
          purchasedNumberColors: ['num-default'],
          selectedNumberColor: 'num-default',
          purchasedSkills: [],
          enabledSkills: [],
          purchasedSoundPacks: ['snd-zen'],
          selectedSoundPack: 'snd-zen',
          purchasedBundles: [],
          bonusClaimed: false,
          nextBonusClaimTime: 0,
          starterPackPurchased: false,
          unlockedPack2: [],
          unlockedPack3: [],
      };

      return initialData;
    }
    const data = JSON.parse(raw);

    // Migrations
    if (typeof data.points !== 'number') data.points = 0;

    if (!data.purchasedBackgrounds) data.purchasedBackgrounds = ['bg-default', 'bg-dyn-default'];
    if (!data.purchasedBackgrounds.includes('bg-default')) data.purchasedBackgrounds.push('bg-default');
    if (!data.purchasedBackgrounds.includes('bg-dyn-default')) data.purchasedBackgrounds.push('bg-dyn-default');

    if (data.selectedBackground === undefined) data.selectedBackground = 'bg-default';

    if (!data.purchasedNumberColors) data.purchasedNumberColors = ['num-default'];
    if (!data.selectedNumberColor) data.selectedNumberColor = 'num-default';

    if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
    if (!data.selectedSoundPack) data.selectedSoundPack = 'snd-zen';

    if (data.settings.vibration === undefined) data.settings.vibration = true;

    if (data.settings.showTimer === undefined) {
        if ((data.settings as any).hideTimer !== undefined) {
            data.settings.showTimer = !(data.settings as any).hideTimer;
            delete (data.settings as any).hideTimer;
        } else {
            data.settings.showTimer = true;
        }
    }

    if (data.settings.autoEraseNotes === undefined) data.settings.autoEraseNotes = true;
    if (data.settings.digitFirst === undefined) data.settings.digitFirst = false;
    if (data.settings.screenWakeLock === undefined) data.settings.screenWakeLock = false;
    if (data.settings.generateReplay === undefined) data.settings.generateReplay = true; // Default ON

    if (data.settings.appearance === undefined) {
        data.settings.appearance = 'light'; 
    }

    if (!data.purchasedSkills) data.purchasedSkills = [];
    if (!data.enabledSkills) data.enabledSkills = [...data.purchasedSkills]; // Default new field to existing purchased skills
    if (!data.purchasedBundles) data.purchasedBundles = [];

    if (data.bonusClaimed === undefined) data.bonusClaimed = false;
    if (data.nextBonusClaimTime === undefined) data.nextBonusClaimTime = 0;

    if (data.starterPackPurchased === undefined) data.starterPackPurchased = false;

    if (!data.unlockedPack2) data.unlockedPack2 = [];
    if (!data.unlockedPack3) data.unlockedPack3 = [];

    return data;
  } catch (e) {
    console.error("Failed to load data", e);
    return { 
        settings: DEFAULT_SETTINGS, 
        points: 0, 
        progress: {},
        purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
        selectedBackground: 'bg-default',
        purchasedNumberColors: ['num-default'],
        selectedNumberColor: 'num-default',
        purchasedSkills: [],
        enabledSkills: [],
        purchasedSoundPacks: ['snd-zen'],
        selectedSoundPack: 'snd-zen',
        purchasedBundles: [],
        bonusClaimed: false,
        nextBonusClaimTime: 0,
        starterPackPurchased: false,
        unlockedPack2: [],
        unlockedPack3: [],
    };
  }
}

function saveData(data: StoredData) {
  try {
    const stringified = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, stringified);
    Preferences.set({
        key: STORAGE_KEY,
        value: stringified
    }).catch(err => console.error("Native save failed", err));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getStoredData, 

  initializeNative: async (): Promise<StoredData | null> => {
      try {
          const { value } = await Preferences.get({ key: STORAGE_KEY });
          if (value) {
              localStorage.setItem(STORAGE_KEY, value);
              return JSON.parse(value);
          }
          return null;
      } catch (e) {
          console.warn("Could not read native prefs", e);
          return null;
      }
  },

  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getPoints: (): number => {
    return getStoredData().points;
  },

  addPoints: (amount: number) => {
    const data = getStoredData();
    data.points += amount;
    saveData(data);
    return data.points;
  },

  getPurchasedBackgrounds: (): string[] => {
      return getStoredData().purchasedBackgrounds;
  },

  getSelectedBackground: (): string | null => {
      return getStoredData().selectedBackground;
  },

  purchaseBackground: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedBackgrounds.includes(id)) {
          data.points -= cost;
          data.purchasedBackgrounds.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectBackground: (id: string | null) => {
      const data = getStoredData();
      data.selectedBackground = id;
      saveData(data);
  },

  getPurchasedNumberColors: (): string[] => {
      return getStoredData().purchasedNumberColors;
  },

  getSelectedNumberColor: (): string => {
      return getStoredData().selectedNumberColor;
  },

  purchaseNumberColor: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedNumberColors.includes(id)) {
          data.points -= cost;
          data.purchasedNumberColors.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectNumberColor: (id: string) => {
      const data = getStoredData();
      data.selectedNumberColor = id;
      saveData(data);
  },

  getPurchasedSoundPacks: (): string[] => {
    return getStoredData().purchasedSoundPacks || ['snd-zen'];
  },

  getSelectedSoundPack: (): string => {
      return getStoredData().selectedSoundPack || 'snd-zen';
  },

  purchaseSoundPack: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
      if (data.points >= cost && !data.purchasedSoundPacks.includes(id)) {
          data.points -= cost;
          data.purchasedSoundPacks.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectSoundPack: (id: string) => {
      const data = getStoredData();
      data.selectedSoundPack = id;
      saveData(data);
  },

  getPurchasedSkills: (): string[] => {
      return getStoredData().purchasedSkills;
  },

  getEnabledSkills: (): string[] => {
    const data = getStoredData();
    return data.enabledSkills || [];
  },

  purchaseSkill: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedSkills.includes(id)) {
          data.points -= cost;
          data.purchasedSkills.push(id);
          if (!data.enabledSkills) data.enabledSkills = [];
          if (!data.enabledSkills.includes(id)) data.enabledSkills.push(id); // Auto enable on purchase
          saveData(data);
          return true;
      }
      return false;
  },

  toggleSkillEnabled: (id: string) => {
    const data = getStoredData();
    if (!data.enabledSkills) data.enabledSkills = [];
    if (data.enabledSkills.includes(id)) {
      data.enabledSkills = data.enabledSkills.filter(s => s !== id);
    } else if (data.purchasedSkills.includes(id)) {
      data.enabledSkills.push(id);
    }
    saveData(data);
    return data.enabledSkills;
  },

  getPurchasedBundles: (): string[] => {
      return getStoredData().purchasedBundles || [];
  },

  purchaseBundle: (id: string) => {
      const data = getStoredData();
      if (!data.purchasedBundles) data.purchasedBundles = [];
      if (!data.purchasedBundles.includes(id)) {
          data.purchasedBundles.push(id);
          saveData(data);
      }
  },

  isBonusClaimed: (): boolean => {
      return !!getStoredData().bonusClaimed;
  },

  setBonusClaimed: () => {
      const data = getStoredData();
      data.bonusClaimed = true;
      saveData(data);
  },

  getNextBonusClaimTime: (): number => {
      return getStoredData().nextBonusClaimTime || 0;
  },

  setNextBonusClaimTime: (time: number) => {
      const data = getStoredData();
      data.nextBonusClaimTime = time;
      saveData(data);
  },

  isStarterPackPurchased: (): boolean => {
      return !!getStoredData().starterPackPurchased;
  },

  setStarterPackPurchased: () => {
      const data = getStoredData();
      data.starterPackPurchased = true;
      saveData(data);
  },

  getUnlockedPacks2: (): string[] => {
      return getStoredData().unlockedPack2 || [];
  },

  isPack2Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack2?.includes(difficulty) ?? false;
  },

  unlockPack2: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack2) data.unlockedPack2 = [];

      if (data.points >= cost && !data.unlockedPack2.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack2.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getUnlockedPacks3: (): string[] => {
      return getStoredData().unlockedPack3 || [];
  },

  isPack3Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack3?.includes(difficulty) ?? false;
  },

  unlockPack3: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack3) data.unlockedPack3 = [];

      if (data.points >= cost && !data.unlockedPack3.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack3.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    const existing = data.progress[key];
    let bestTime = existing?.bestTime;
    if (progress.status === 'completed') {
        if (bestTime === undefined || progress.timeElapsed < bestTime) {
            bestTime = progress.timeElapsed;
        }
    }
    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };
    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];
           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1 
           };
           saveData(data);
      }
  },

  resetAllData: () => {
    localStorage.removeItem(STORAGE_KEY);
    Preferences.remove({ key: STORAGE_KEY }).catch(() => {});
  },

  getCompletedCount: (difficulty: string, maxLevel: number = 200): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  getCompletedCountInRange: (difficulty: string, minLevel: number, maxLevel: number): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId >= minLevel && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  }
};

import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { Logo } from '../ui/Logo';
import { sounds } from '../../utils/sound';
import { getDifficultyPoints } from '../../utils/constants';

interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
}

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
             {/* Scrollable Content - No Fixed Header */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">

                  {/* Hero Section - Static (Always on screen) */}
                  <div className="flex flex-col items-center mt-12 mb-6">
                      <Logo size={80} className="mb-5 drop-shadow-xl" />
                      <h1 className="text-4xl font-bold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Utility Row (Diamonds + Settings) - Static */}
                  <div className="w-full max-w-md flex items-center justify-end gap-3 mb-8">
                      <div className="flex items-center gap-2 bg-t-surface px-4 py-2.5 rounded-full shadow-sm border border-t-border">
                          <span className="text-lg font-bold text-t-primary tabular-nums leading-none pt-0.5">{points}</span>
                          <div className="text-blue-500"><Icons.Diamond className="w-4 h-4 fill-current" /></div>
                      </div>

                      <button onClick={() => { sounds.playClick(); onOpenSettings(); }} className="p-3 bg-t-surface rounded-full shadow-sm border border-t-border hover:shadow-md transition active:scale-95 text-t-icon">
                          <Icons.Settings className="w-6 h-6" />
                      </button>
                  </div>

                  {/* Difficulty Header - Stagger Step 1 (50ms) */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-bold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid - Stagger Steps 2, 3, 4 (Row based) */}
                  <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-8 shrink-0">
                      {Object.values(Difficulty).map((diff, index) => {
                          const completed = Storage.getCompletedCount(diff, 300);
                          const isPack2Unlocked = Storage.isPack2Unlocked(diff);
                          const isPack3Unlocked = Storage.isPack3Unlocked(diff);

                          let maxLevels = 100;
                          if (isPack2Unlocked) maxLevels = 200;
                          if (isPack3Unlocked) maxLevels = 300;

                          const diffPoints = getDifficultyPoints(diff);

                          // Calculate staggered delay based on row index (0, 1, 2)
                          // Base start 100ms, each row adds 50ms
                          const row = Math.floor(index / 2);
                          const delay = 100 + (row * 50);

                          return (
                              <button 
                                key={diff} 
                                onClick={() => onDifficultySelect(diff)} 
                                style={{ animationDelay: `${delay}ms` }}
                                className="bg-t-surface p-5 rounded-2xl shadow-sm border border-t-border flex flex-col items-start gap-1 active:scale-95 transition-all text-left relative overflow-hidden group opacity-0 animate-slide-in-down"
                              >
                                  <div className="w-full flex justify-between items-start">
                                      <span className="text-lg font-bold text-t-primary leading-tight">{diff}</span>
                                      <div className="flex items-center gap-1 ml-2 shrink-0">
                                          <span className="text-sm font-bold text-t-primary">+{diffPoints}</span>
                                          <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                      </div>
                                  </div>
                                  <span className="text-sm text-t-secondary font-medium tracking-wide mt-1">{completed} / {maxLevels}</span>
                                  <div className="w-full h-1 bg-t-surface-sec rounded-full mt-2 overflow-hidden">
                                      <div className="h-full bg-stone-500" style={{ width: `${Math.min((completed/maxLevels)*100, 100)}%` }}></div>
                                  </div>
                              </button>
                          )
                      })}
                  </div>

                  {/* Footer Actions - Stagger Steps 5, 6 */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More - 250ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down" 
                        style={{ animationDelay: '250ms' }}
                      >
                          {/* Store - Gold */}
                          <button onClick={() => { sounds.playClick(); onOpenStore(); }} className="w-full p-4 bg-[#FFF9C4] dark:bg-amber-900/40 text-amber-900 dark:text-amber-100 border border-amber-200 dark:border-amber-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition relative hover:shadow-md">
                              <Icons.Store className="w-5 h-5" /> <span className="font-bold tracking-wide">Store</span>
                          </button>

                          {/* Get More - Premium Deep Blue */}
                          <button onClick={() => { sounds.playClick(); onOpenDiamondShop(); }} className="w-full p-4 btn-premium-deep text-white rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md overflow-hidden relative">
                              <span className="font-bold tracking-wide relative z-10">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus - 300ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down"
                        style={{ animationDelay: '300ms' }}
                      >
                          {/* Stats - Blue */}
                          <button onClick={() => { sounds.playClick(); onOpenStats(); }} className="w-full p-4 bg-blue-100 dark:bg-blue-900/40 text-blue-900 dark:text-blue-100 border border-blue-200 dark:border-blue-800 rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md">
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-bold tracking-wide">Stats</span>
                          </button>

                          {/* Daily Bonus - Green */}
                          <button 
                              onClick={onClaimBonus} 
                              disabled={!!timeLeft}
                              className={`w-full p-4 border rounded-2xl shadow-sm flex items-center justify-center gap-2 transition overflow-hidden relative ${
                                  !!timeLeft 
                                  ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed' 
                                  : 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-900 dark:text-emerald-100 border-emerald-200 dark:border-emerald-800 hover:shadow-md active:scale-95'
                              }`}
                          >
                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-5 h-5" />
                                      <span className="font-bold tabular-nums">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-bold tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS, SKILLS } from './utils/constants';
import { motion, AnimatePresence } from 'framer-motion';

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [purchasedBundles, setPurchasedBundles] = useState<string[]>(Storage.getPurchasedBundles());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Initialize Native Storage
  useEffect(() => {
    const initStorage = async () => {
        const nativeData = await Storage.initializeNative();
        if (nativeData) {
            setPoints(nativeData.points);
            setSettings(nativeData.settings);
            setPurchasedBackgrounds(nativeData.purchasedBackgrounds);
            setPurchasedNumberColors(nativeData.purchasedNumberColors);
            setPurchasedSoundPacks(nativeData.purchasedSoundPacks || ['snd-zen']);
            setSelectedSoundPackId(nativeData.selectedSoundPack || 'snd-zen');
            setPurchasedSkills(nativeData.purchasedSkills);
            setEnabledSkills(nativeData.enabledSkills || [...nativeData.purchasedSkills]);
            setPurchasedBundles(nativeData.purchasedBundles || []);
            setStarterPackPurchased(nativeData.starterPackPurchased || false);

            const isDark = nativeData.settings.appearance === 'dark' || (nativeData.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
            if (isDark) document.documentElement.classList.add('dark');
            else document.documentElement.classList.remove('dark');
        }
    };
    initStorage();
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setPurchasedBundles(Storage.getPurchasedBundles());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = () => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();
    const nextTime = now + (24 * 60 * 60 * 1000); 
    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(50);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.type === 'bundle' && purchasedBundles.includes(offer.id)) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;
      handleEarnPoints(offer.diamonds);
      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseNumberColor('num-purple', 0);
          Storage.purchaseNumberColor('num-teal', 0);
      } else if (offer.type === 'bundle') {
          Storage.purchaseBundle(offer.id);
          setPurchasedBundles([...purchasedBundles, offer.id]);
          if (offer.id === 'bundle_skill') {
              Storage.purchaseSkill('skill-auto', 0);
              Storage.purchaseSkill('skill-scan', 0);
          } else if (offer.id === 'bundle_cosmetic') {
              ALL_BACKGROUNDS.forEach(bg => Storage.purchaseBackground(bg.id, 0));
          } else if (offer.id === 'bundle_pro') {
              SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
              Storage.purchaseNumberColor('num-rgb', 0);
          }
      }
      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleAddDevPoints = () => {
      handleEarnPoints(5000);
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 
  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50 dark:bg-stone-900"; 
  } else if (screen === 'game') {
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Stack" Transition
  // Forward: Enter from right, Exit slightly left (Push)
  // Back: Enter from left, Exit to right (Pop)
  const variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-25%' : 0),
      opacity: dir < 0 ? 0.5 : 1, // Dim when entering from back
      scale: dir < 0 ? 0.95 : 1,
      zIndex: dir > 0 ? 10 : 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      scale: 1,
      zIndex: 1,
      transition: { 
          type: "spring", 
          stiffness: 350, 
          damping: 35,
          mass: 1 
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-25%' : '100%',
      opacity: dir > 0 ? 0.5 : 1,
      scale: dir > 0 ? 0.95 : 1,
      zIndex: dir < 0 ? 10 : 0,
      transition: { 
          type: "spring", 
          stiffness: 350, 
          damping: 35,
          mass: 1 
      }
    })
  };

  return (
      <>
          {/* Background Layer (Persistent) */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
            style={{ width: '100%', height: '100%' }}
          />
          <div 
            className="fixed inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
            style={{ opacity: overlayOpacity }} 
          />

          {/* Screen Content Layer (Animated) */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <AnimatePresence mode="popLayout" custom={direction}>
                <motion.div
                    key={screen}
                    custom={direction}
                    variants={variants}
                    initial="initial"
                    animate="animate"
                    exit="exit"
                    className="w-full h-full absolute inset-0 flex flex-col bg-transparent"
                >
                    {screen === 'splash' && <SplashScreen />}

                    {screen === 'difficulty' && (
                        <DifficultyScreen 
                            points={points}
                            onDifficultySelect={handleDifficultySelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onOpenStore={() => navigate('store', 'forward')}
                            onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                            onClaimBonus={handleClaimBonus}
                            onOpenStats={() => navigate('stats', 'forward')}
                            nextBonusClaimTime={nextBonusClaimTime}
                        />
                    )}

                    {screen === 'diamondShop' && (
                        <DiamondShopScreen 
                            points={points}
                            onBack={handleDiamondShopBack}
                            onWatchAd={handleWatchAd}
                            onBuyOffer={handleBuyOffer}
                            starterPackPurchased={starterPackPurchased}
                            purchasedBundles={purchasedBundles}
                        />
                    )}

                    {screen === 'stats' && (
                        <StatsScreen 
                            onBack={handleStatsBack}
                        />
                    )}

                    {screen === 'levels' && selectedDifficulty && (
                        <LevelsScreen 
                            difficulty={selectedDifficulty}
                            points={points}
                            unlockedPacks2={unlockedPacks2}
                            unlockedPacks3={unlockedPacks3}
                            onBack={handleLevelBack}
                            onLevelSelect={handleLevelSelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onUnlockPack2={handleUnlockPack2}
                            onUnlockPack3={handleUnlockPack3}
                        />
                    )}

                    {screen === 'store' && (
                        <StoreScreen 
                            points={points}
                            onBack={handleStoreBack}
                            purchasedSkills={purchasedSkills}
                            enabledSkills={enabledSkills}
                            purchasedBackgrounds={purchasedBackgrounds}
                            purchasedNumberColors={purchasedNumberColors}
                            purchasedSoundPacks={purchasedSoundPacks}
                            selectedBackgroundId={selectedBackgroundId}
                            selectedNumberColorId={selectedNumberColorId}
                            selectedSoundPackId={selectedSoundPackId}
                            onPurchase={initiatePurchase}
                            onSelectBackground={handleSelectBackground}
                            onSelectNumberColor={handleSelectNumberColor}
                            onSelectSoundPack={handleSelectSoundPack}
                            onToggleSkill={handleToggleSkill}
                        />
                    )}

                    {screen === 'game' && selectedDifficulty && selectedLevel && (
                        <SudokuGame
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {
                                setPoints(Storage.getPoints());
                            }}
                            onSettingsOpen={() => setShowSettings(true)}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={enabledSkills} // Pass only enabled skills to game
                        />
                    )}
                </motion.div>
            </AnimatePresence>

            {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                    onAddDevPoints={handleAddDevPoints}
                />
            )}
            {replayLevelId !== null && selectedDifficulty && (
                <ReplayModal 
                    levelId={replayLevelId}
                    onConfirm={confirmReplay}
                    onCancel={() => setReplayLevelId(null)}
                />
            )}
            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}
            {paymentOffer && (
                <PaymentModal
                    offer={paymentOffer}
                    onComplete={finalizeRealMoneyPurchase}
                    onCancel={() => setPaymentOffer(null)}
                />
            )}
            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onGetMore={handleNavigateToShop} 
                    onGoPlay={handleGoPlay} 
                />
            )}
            {isWatchingAd && <AdOverlay />}
          </div>
      </>
  );
}

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS, SKILLS } from './utils/constants';
import { motion, AnimatePresence } from 'framer-motion';

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [purchasedBundles, setPurchasedBundles] = useState<string[]>(Storage.getPurchasedBundles());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Initialize Native Storage
  useEffect(() => {
    const initStorage = async () => {
        const nativeData = await Storage.initializeNative();
        if (nativeData) {
            setPoints(nativeData.points);
            setSettings(nativeData.settings);
            setPurchasedBackgrounds(nativeData.purchasedBackgrounds);
            setPurchasedNumberColors(nativeData.purchasedNumberColors);
            setPurchasedSoundPacks(nativeData.purchasedSoundPacks || ['snd-zen']);
            setSelectedSoundPackId(nativeData.selectedSoundPack || 'snd-zen');
            setPurchasedSkills(nativeData.purchasedSkills);
            setEnabledSkills(nativeData.enabledSkills || [...nativeData.purchasedSkills]);
            setPurchasedBundles(nativeData.purchasedBundles || []);
            setStarterPackPurchased(nativeData.starterPackPurchased || false);

            const isDark = nativeData.settings.appearance === 'dark' || (nativeData.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
            if (isDark) document.documentElement.classList.add('dark');
            else document.documentElement.classList.remove('dark');
        }
    };
    initStorage();
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setPurchasedBundles(Storage.getPurchasedBundles());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = () => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();
    const nextTime = now + (24 * 60 * 60 * 1000); 
    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(50);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.type === 'bundle' && purchasedBundles.includes(offer.id)) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;
      handleEarnPoints(offer.diamonds);
      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseNumberColor('num-purple', 0);
          Storage.purchaseNumberColor('num-teal', 0);
      } else if (offer.type === 'bundle') {
          Storage.purchaseBundle(offer.id);
          setPurchasedBundles([...purchasedBundles, offer.id]);
          if (offer.id === 'bundle_skill') {
              Storage.purchaseSkill('skill-auto', 0);
              Storage.purchaseSkill('skill-scan', 0);
          } else if (offer.id === 'bundle_cosmetic') {
              ALL_BACKGROUNDS.forEach(bg => Storage.purchaseBackground(bg.id, 0));
          } else if (offer.id === 'bundle_pro') {
              SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
              Storage.purchaseNumberColor('num-rgb', 0);
          }
      }
      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleAddDevPoints = () => {
      handleEarnPoints(5000);
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 
  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50 dark:bg-stone-900"; 
  } else if (screen === 'game') {
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Stack" Transition
  // Optimized for smoothness without "cuts"
  const variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-30%' : 0),
      opacity: dir < 0 ? 0.6 : 1, // Dim incoming background screen
      scale: dir < 0 ? 0.95 : 1,
      zIndex: dir > 0 ? 20 : 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      scale: 1,
      zIndex: 10,
      transition: { 
          type: "spring", 
          stiffness: 300, 
          damping: 30,
          mass: 1 
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-30%' : '100%',
      opacity: dir > 0 ? 0.6 : 1, // Dim outgoing background screen
      scale: dir > 0 ? 0.95 : 1,
      zIndex: dir < 0 ? 20 : 0,
      transition: { 
          type: "spring", 
          stiffness: 300, 
          damping: 30,
          mass: 1
      }
    })
  };

  return (
      <>
          {/* Background Layer (Persistent) */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
            style={{ width: '100%', height: '100%' }}
          />
          <div 
            className="fixed inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
            style={{ opacity: overlayOpacity }} 
          />

          {/* Screen Content Layer (Animated) */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <AnimatePresence custom={direction} initial={false}>
                <motion.div
                    key={screen}
                    custom={direction}
                    variants={variants}
                    initial="initial"
                    animate="animate"
                    exit="exit"
                    className="w-full h-full absolute inset-0 flex flex-col bg-transparent"
                    style={{ pointerEvents: 'auto' }}
                >
                    {screen === 'splash' && <SplashScreen />}

                    {screen === 'difficulty' && (
                        <DifficultyScreen 
                            points={points}
                            onDifficultySelect={handleDifficultySelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onOpenStore={() => navigate('store', 'forward')}
                            onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                            onClaimBonus={handleClaimBonus}
                            onOpenStats={() => navigate('stats', 'forward')}
                            nextBonusClaimTime={nextBonusClaimTime}
                        />
                    )}

                    {screen === 'diamondShop' && (
                        <DiamondShopScreen 
                            points={points}
                            onBack={handleDiamondShopBack}
                            onWatchAd={handleWatchAd}
                            onBuyOffer={handleBuyOffer}
                            starterPackPurchased={starterPackPurchased}
                            purchasedBundles={purchasedBundles}
                        />
                    )}

                    {screen === 'stats' && (
                        <StatsScreen 
                            onBack={handleStatsBack}
                        />
                    )}

                    {screen === 'levels' && selectedDifficulty && (
                        <LevelsScreen 
                            difficulty={selectedDifficulty}
                            points={points}
                            unlockedPacks2={unlockedPacks2}
                            unlockedPacks3={unlockedPacks3}
                            onBack={handleLevelBack}
                            onLevelSelect={handleLevelSelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onUnlockPack2={handleUnlockPack2}
                            onUnlockPack3={handleUnlockPack3}
                        />
                    )}

                    {screen === 'store' && (
                        <StoreScreen 
                            points={points}
                            onBack={handleStoreBack}
                            purchasedSkills={purchasedSkills}
                            enabledSkills={enabledSkills}
                            purchasedBackgrounds={purchasedBackgrounds}
                            purchasedNumberColors={purchasedNumberColors}
                            purchasedSoundPacks={purchasedSoundPacks}
                            selectedBackgroundId={selectedBackgroundId}
                            selectedNumberColorId={selectedNumberColorId}
                            selectedSoundPackId={selectedSoundPackId}
                            onPurchase={initiatePurchase}
                            onSelectBackground={handleSelectBackground}
                            onSelectNumberColor={handleSelectNumberColor}
                            onSelectSoundPack={handleSelectSoundPack}
                            onToggleSkill={handleToggleSkill}
                        />
                    )}

                    {screen === 'game' && selectedDifficulty && selectedLevel && (
                        <SudokuGame
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {
                                setPoints(Storage.getPoints());
                            }}
                            onSettingsOpen={() => setShowSettings(true)}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={enabledSkills} // Pass only enabled skills to game
                        />
                    )}
                </motion.div>
            </AnimatePresence>

            {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                    onAddDevPoints={handleAddDevPoints}
                />
            )}
            {replayLevelId !== null && selectedDifficulty && (
                <ReplayModal 
                    levelId={replayLevelId}
                    onConfirm={confirmReplay}
                    onCancel={() => setReplayLevelId(null)}
                />
            )}
            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}
            {paymentOffer && (
                <PaymentModal
                    offer={paymentOffer}
                    onComplete={finalizeRealMoneyPurchase}
                    onCancel={() => setPaymentOffer(null)}
                />
            )}
            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onGetMore={handleNavigateToShop} 
                    onGoPlay={handleGoPlay} 
                />
            )}
            {isWatchingAd && <AdOverlay />}
          </div>
      </>
  );
}

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS, SKILLS } from './utils/constants';
import { motion, AnimatePresence } from 'framer-motion';

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [purchasedBundles, setPurchasedBundles] = useState<string[]>(Storage.getPurchasedBundles());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Initialize Native Storage
  useEffect(() => {
    const initStorage = async () => {
        const nativeData = await Storage.initializeNative();
        if (nativeData) {
            setPoints(nativeData.points);
            setSettings(nativeData.settings);
            setPurchasedBackgrounds(nativeData.purchasedBackgrounds);
            setPurchasedNumberColors(nativeData.purchasedNumberColors);
            setPurchasedSoundPacks(nativeData.purchasedSoundPacks || ['snd-zen']);
            setSelectedSoundPackId(nativeData.selectedSoundPack || 'snd-zen');
            setPurchasedSkills(nativeData.purchasedSkills);
            setEnabledSkills(nativeData.enabledSkills || [...nativeData.purchasedSkills]);
            setPurchasedBundles(nativeData.purchasedBundles || []);
            setStarterPackPurchased(nativeData.starterPackPurchased || false);

            const isDark = nativeData.settings.appearance === 'dark' || (nativeData.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
            if (isDark) document.documentElement.classList.add('dark');
            else document.documentElement.classList.remove('dark');
        }
    };
    initStorage();
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setPurchasedBundles(Storage.getPurchasedBundles());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = () => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();
    const nextTime = now + (24 * 60 * 60 * 1000); 
    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(50);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.type === 'bundle' && purchasedBundles.includes(offer.id)) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;
      handleEarnPoints(offer.diamonds);
      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseNumberColor('num-purple', 0);
          Storage.purchaseNumberColor('num-teal', 0);
      } else if (offer.type === 'bundle') {
          Storage.purchaseBundle(offer.id);
          setPurchasedBundles([...purchasedBundles, offer.id]);
          if (offer.id === 'bundle_skill') {
              Storage.purchaseSkill('skill-auto', 0);
              Storage.purchaseSkill('skill-scan', 0);
          } else if (offer.id === 'bundle_cosmetic') {
              ALL_BACKGROUNDS.forEach(bg => Storage.purchaseBackground(bg.id, 0));
          } else if (offer.id === 'bundle_pro') {
              SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
              Storage.purchaseNumberColor('num-rgb', 0);
          }
      }
      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleAddDevPoints = () => {
      handleEarnPoints(5000);
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 
  if (screen === 'splash') {
      activeBackgroundClass = "bg-stone-50 dark:bg-stone-900"; 
  } else if (screen === 'game') {
      if (selectedBackgroundId) {
          const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
          if (bg) {
              activeBackgroundClass = bg.class;
          }
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Slide" Transition
  // Using 100% width slide to prevent cuts and ensure screens move completely off-view
  const variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Background Layer (Persistent) */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
            style={{ width: '100%', height: '100%' }}
          />
          <div 
            className="fixed inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
            style={{ opacity: overlayOpacity }} 
          />

          {/* Screen Content Layer (Animated) */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <AnimatePresence custom={direction} initial={false}>
                <motion.div
                    key={screen}
                    custom={direction}
                    variants={variants}
                    initial="initial"
                    animate="animate"
                    exit="exit"
                    className="w-full h-full absolute inset-0 flex flex-col bg-transparent"
                    style={{ pointerEvents: 'auto' }}
                >
                    {screen === 'splash' && <SplashScreen />}

                    {screen === 'difficulty' && (
                        <DifficultyScreen 
                            points={points}
                            onDifficultySelect={handleDifficultySelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onOpenStore={() => navigate('store', 'forward')}
                            onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                            onClaimBonus={handleClaimBonus}
                            onOpenStats={() => navigate('stats', 'forward')}
                            nextBonusClaimTime={nextBonusClaimTime}
                        />
                    )}

                    {screen === 'diamondShop' && (
                        <DiamondShopScreen 
                            points={points}
                            onBack={handleDiamondShopBack}
                            onWatchAd={handleWatchAd}
                            onBuyOffer={handleBuyOffer}
                            starterPackPurchased={starterPackPurchased}
                            purchasedBundles={purchasedBundles}
                        />
                    )}

                    {screen === 'stats' && (
                        <StatsScreen 
                            onBack={handleStatsBack}
                        />
                    )}

                    {screen === 'levels' && selectedDifficulty && (
                        <LevelsScreen 
                            difficulty={selectedDifficulty}
                            points={points}
                            unlockedPacks2={unlockedPacks2}
                            unlockedPacks3={unlockedPacks3}
                            onBack={handleLevelBack}
                            onLevelSelect={handleLevelSelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onUnlockPack2={handleUnlockPack2}
                            onUnlockPack3={handleUnlockPack3}
                        />
                    )}

                    {screen === 'store' && (
                        <StoreScreen 
                            points={points}
                            onBack={handleStoreBack}
                            purchasedSkills={purchasedSkills}
                            enabledSkills={enabledSkills}
                            purchasedBackgrounds={purchasedBackgrounds}
                            purchasedNumberColors={purchasedNumberColors}
                            purchasedSoundPacks={purchasedSoundPacks}
                            selectedBackgroundId={selectedBackgroundId}
                            selectedNumberColorId={selectedNumberColorId}
                            selectedSoundPackId={selectedSoundPackId}
                            onPurchase={initiatePurchase}
                            onSelectBackground={handleSelectBackground}
                            onSelectNumberColor={handleSelectNumberColor}
                            onSelectSoundPack={handleSelectSoundPack}
                            onToggleSkill={handleToggleSkill}
                        />
                    )}

                    {screen === 'game' && selectedDifficulty && selectedLevel && (
                        <SudokuGame
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {
                                setPoints(Storage.getPoints());
                            }}
                            onSettingsOpen={() => setShowSettings(true)}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={enabledSkills} // Pass only enabled skills to game
                        />
                    )}
                </motion.div>
            </AnimatePresence>

            {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                    onAddDevPoints={handleAddDevPoints}
                />
            )}
            {replayLevelId !== null && selectedDifficulty && (
                <ReplayModal 
                    levelId={replayLevelId}
                    onConfirm={confirmReplay}
                    onCancel={() => setReplayLevelId(null)}
                />
            )}
            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}
            {paymentOffer && (
                <PaymentModal
                    offer={paymentOffer}
                    onComplete={finalizeRealMoneyPurchase}
                    onCancel={() => setPaymentOffer(null)}
                />
            )}
            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onGetMore={handleNavigateToShop} 
                    onGoPlay={handleGoPlay} 
                />
            )}
            {isWatchingAd && <AdOverlay />}
          </div>
      </>
  );
}

import React, { useState } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else if (!isSelected) {
            onSelectSoundPack(pack.id);
        }
    };

    const handleSkillInteraction = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);
        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            sounds.playClick();
            onToggleSkill(skill.id);
        }
    };

    // Shared Price Footer component for grid items
    const ItemFooter = ({ isPurchased, isSelected, cost }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-7 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[13px] font-bold text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                </div>
            );
        }
        return null;
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
             {/* Locked Header */}
             <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Store</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Personalize</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border relative z-30">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-10 pt-2">

                      {/* SKILLS SECTION - Redesigned List View */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Skills</h2>
                          <div className="flex flex-col gap-3">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);

                                  return (
